import {config,clone,groups,configureCatalog,validateProgress,parseImport,clearId,baseCharacters,levelCount,characterCount,matrixCount,condition,stageComplete,unlocked} from './model.js';
const source=import.meta.url.includes('/dist/');
const {createStore}=await import(new URL(source?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
await import(new URL(source?'../../talos2/dist/shared/sync-core.js':'../../shared/merge-core.js',import.meta.url));
const core=window.SideProjectSync,$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={overview:'坑道總覽',roadmap:'八層 Roadmap',matrix:'角色通關矩陣',trophies:'64 座獎盃',buildings:'基地與角色解鎖',recipes:'Evolution 與 Passive',encyclopedia:'Encyclopedia',advice:'角色配裝與基地',sources:'來源與覆蓋'};
const setNames={base:'本體',regal:'Regal 更新',shadow:'Shadow 更新',naturalist:'Naturalist 更新',unknown:'更新歸屬待查'};
const categoryNames={resource:'資源地塊',housing:'角色住房',economy:'經濟生產',function:'功能建築',trophy:'獎盃建築'};
let data,progress,blocked=false,review,refreshQueued=false;
const peek=new Set(),filters={search:'',status:'all',set:'all',category:'all',level:'all',character:'all',sort:'default',orientation:'characters',kind:'all',mobileAxis:'level',mobileLevel:'bonexyard',mobileCharacter:'warrior'};
const view=()=>Object.hasOwn(names,new URL(location.href).searchParams.get('view'))?new URL(location.href).searchParams.get('view'):'overview';
const stage=()=>new URL(location.href).searchParams.get('level')||data.levels[0].id;
const message=text=>$('message').textContent=text;
const route=(v,extra={})=>'?'+new URLSearchParams({view:v,...extra});
const link=(v,text,extra={})=>`<a data-route href="${esc(route(v,extra))}">${esc(text)}</a>`;
const options=(rows,current)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`).join('');
const select=(key,label,rows)=>`<label>${label}<select id="filter-${key}" data-filter="${key}">${options(rows,filters[key])}</select></label>`;
const search=()=>'<label>搜尋名稱／內容<input type="search" id="search" data-filter="search" placeholder="輸入名稱或材料" value="'+esc(filters.search)+'"></label>';
const match=(...values)=>values.flat().join(' ').toLowerCase().includes(filters.search.toLowerCase());
const scopeFilter=()=>select('set','內容範圍',[['all','本體與免費更新'],...Object.entries(setNames)]);
const statusFilter=()=>select('status','進度',[['all','全部'],['pending','未完成'],['done','已完成']]);
const statusMatch=done=>filters.status==='all'||(filters.status==='done'?done:!done);
function checkbox(group,id,label,instance=''){return `<label class="check"><input type="checkbox" id="${esc(instance+group+'-'+id)}" data-group="${group}" data-id="${esc(id)}" ${progress[group][id]?'checked':''} ${blocked?'disabled':''}><span>${esc(label)}</span></label>`;}
const sourceLinks=row=>row.sourceIds.map(id=>{const s=data.sourceRefs.find(s=>s.id===id);return s&&s.access!=='local_spec'?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`:esc(id);}).join(' · ');
const verification=row=>row.verification==='pending'?'待查':row.verification==='conflict'?'來源有差異':row.sourceIds.some(id=>data.sourceRefs.find(s=>s.id===id)?.access==='search_index')?'搜尋索引核對':'規格來源已核對';
const metadata=row=>`<div class="meta"><span class="tag">${esc(setNames[row.contentSet]||'歸屬待查')}</span>${esc(verification(row))} · ${sourceLinks(row)}</div>`;
const counted=(map,rows)=>rows.filter(r=>map[r.id]).length;
const store=createStore(config,core,()=>{if(refreshQueued)return;refreshQueued=true;queueMicrotask(async()=>{refreshQueued=false;try{progress=await store.get();if(review&&JSON.stringify(progress)!==review.stamp){review.stale=true;$('import-status').textContent='預覽已過期；本機進度已變更，請取消後重新比較。';importControls();}render(true);}catch(e){blocked=true;message(e.message);}});});
async function action(fn){try{await fn();}catch(e){message(e.message);$('backup-status').textContent=e.message;}}
function navigate(v,extra={}){history.pushState(null,'',route(v,extra));Object.assign(filters,{search:'',status:'all',set:'all',category:'all',level:'all',character:'all',sort:'default',kind:'all'});if(data.levels.some(l=>l.id===extra.level))filters.level=filters.mobileLevel=extra.level;if(data.characters.some(c=>c.id===extra.character))filters.character=filters.mobileCharacter=extra.character;render();document.querySelector('.rail').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');$('app').focus();window.scrollTo(0,0);}
function roadmapCard(level){
 const done=stageComplete(progress,data,level),compact=done&&!peek.has(level.id),step=data.roadmapSteps.find(s=>s.levelId===level.id);
 const buildings=data.buildings.filter(b=>b.blueprintLevel===level.id),clears=levelCount(progress,data,level.id);
 return `<article class="step ${compact?'compact':''}" id="stage-${level.id}" data-stage="${level.id}"><div class="step-head"><div class="step-title"><h2>${level.order}. ${esc(level.name)}</h2><span class="count">${done?'檢查完成':'待完成'} · ${clears}/16</span></div>${done?`<button data-peek="${level.id}">${compact?'回看攻略':'收合攻略'}</button>`:''}</div><div class="checks">${checkbox('stepDone',step.id,step.name)}${link('matrix','記錄本關角色通關',{level:level.id})}</div><div class="step-body"><div><h3>現在去哪</h3><p>${esc(level.location)}</p><p class="meta">${esc(level.gearRule)}</p></div><div><h3>現在做什麼</h3><p>${esc(level.action)}</p></div><div><h3>離開前檢查</h3><p>${esc(level.check)}</p></div><div><h3>錯過怎麼補救</h3><p>${esc(level.recovery)}</p></div><div class="linked"><p class="meta">${esc(level.boss)}</p><details><summary>本層藍圖與建造 · ${counted(progress.buildingBuilt,buildings)}/${buildings.length} 已建造</summary><div class="building-links">${buildings.map(b=>`<div><strong>${esc(b.name)}</strong>${checkbox('blueprintObtained',b.id,'取得藍圖')}${checkbox('buildingBuilt',b.id,'已建造')}</div>`).join('')}</div></details>${metadata(level)}</div></div></article>`;
}
function overview(){const next=data.levels.find(l=>!stageComplete(progress,data,l))||data.levels[0],earned=counted(progress.trophyEarned,data.trophies),matrix=matrixCount(progress,data);return `<h1>坑道總覽</h1><p class="lead">${matrix===0?'從 BONExYARD 開始。':'繼續清理角色與關卡。'} 先首通、回基地擴充角色，再補每關十人與角色全八關。所有章節都可直接閱讀。</p><div class="stats"><div class="stat"><span>PS5 獎盃</span><strong id="trophy-count">${earned} / 64</strong></div><div class="stat"><span>本體角色通關</span><strong id="matrix-count">${matrix} / 128</strong></div><div class="stat"><span>基地已建造（本站收錄）</span><strong>${counted(progress.buildingBuilt,data.buildings)} / ${data.buildings.length}</strong></div><div class="stat"><span>已製作配方（本站收錄）</span><strong>${counted(progress.recipeMade,data.recipes)} / ${data.recipes.length}</strong></div></div><div class="overview-grid"><section><div class="panel next"><div><small>推薦下一步</small><h2>${esc(next.name)}</h2></div>${link('roadmap','前往本層',{level:next.id})}</div>${roadmapCard(next)}<h2>最近未完成事項</h2><ul class="layers">${data.roadmapSteps.filter(s=>!progress.stepDone[s.id]).slice(0,3).map(s=>`<li>${link('roadmap',data.levels.find(l=>l.id===s.levelId).name+' · '+s.name,{level:s.levelId})}</li>`).join('')||'<li>各層檢查已記錄，繼續核對 PS5 獎盃與收集缺口。</li>'}</ul></section><section><h2>八層 Pit Lift</h2><ol class="layers">${data.levels.map(l=>`<li><div>${link('roadmap',l.order+'. '+l.name,{level:l.id})}<div class="progress-bar"><span style="width:${levelCount(progress,data,l.id)/16*100}%"></span></div></div><span class="count">${levelCount(progress,data,l.id)} / 16</span></li>`).join('')}</ol></section></div>`;}
function roadmap(){const chosen=stage(),levels=chosen==='all'?data.levels:data.levels.filter(l=>l.id===chosen);return `<h1>八層 Roadmap</h1><p class="lead">首通優先解鎖下一層與藍圖；沒有清空上一層的門檻。每次進坑選尚未通關的角色，結束後記錄該角色×該關。Gear 精確跨層門檻待查。</p><div class="toolbar"><label>章節直達<select id="stage-select">${options([['all','全部八層'],...data.levels.map(l=>[l.id,l.order+'. '+l.name])],chosen)}</select></label>${search()}</div><p class="notice">War Room 自動通關、更新角色是否計入 Conquered 與 NG+ 例外待實機；不自動取得獎盃。Endless／NG+ 屬推薦體驗，不追加白金矩陣。</p>${levels.filter(l=>match(l.name,l.action,l.check,l.recovery)).map(roadmapCard).join('')||empty()}<section class="panel"><h2>白金收尾順序</h2><ol><li>核對八關首通與終局獎盃；缺 Gear 時選未通關角色回刷目標關卡的緊接前一層。</li><li>矩陣按差幾格排序，補角色全八關與每關至少十名不同角色。</li><li>建造指定建築，核對 15 座住房、擴張 5 次、單次 harvest 與累積資源門檻。</li><li>製作五個特殊配方；Scholar 只核對本體圖鑑，本站清單不能當作完整分母。</li><li>PS5 實際跳盃後再獨立勾選獎盃。</li></ol></section>`;}
function empty(){return '<p class="empty">沒有符合條件的已收錄項目。可清除搜尋或切回全部範圍；來源缺口見「來源與覆蓋」。</p>';}
function matrix(){let chars=data.characters.filter(c=>(filters.set==='all'||c.contentSet===filters.set)&&match(c.name,c.housing)&&(filters.character==='all'||c.id===filters.character));const levels=data.levels.filter(l=>filters.level==='all'||l.id===filters.level);
 if(filters.sort==='remaining')chars.sort((a,b)=>(8-characterCount(progress,data,a.id))-(8-characterCount(progress,data,b.id)));
 if(filters.sort==='unlocked')chars.sort((a,b)=>Number(unlocked(progress,b))-Number(unlocked(progress,a)));
 chars=chars.filter(c=>filters.status==='all'||(filters.status==='done'?characterCount(progress,data,c.id)===8:characterCount(progress,data,c.id)<8));
 const cell=(c,l)=>`<td><label><input type="checkbox" data-group="clears" data-id="${clearId(c.id,l.id)}" id="clears-${clearId(c.id,l.id)}" aria-label="${esc(c.name+' × '+l.name)}" ${progress.clears[clearId(c.id,l.id)]?'checked':''}></label></td>`;
 const charName=c=>`<span class="matrix-name">${esc(c.name)}</span><small>${characterCount(progress,data,c.id)}/8 · ${unlocked(progress,c)?'已開放':'住房待建'} · ${esc(setNames[c.contentSet])}</small>`;
 const table=(list)=>filters.orientation==='characters'?`<table><thead><tr><th scope="col">角色／本體關卡</th>${levels.map(l=>`<th scope="col">${esc(l.name)}<br>${levelCount(progress,data,l.id)}/16 本體角色</th>`).join('')}</tr></thead><tbody>${list.map(c=>`<tr><th scope="row">${charName(c)}</th>${levels.map(l=>cell(c,l)).join('')}</tr>`).join('')}</tbody></table>`:`<table><thead><tr><th scope="col">關卡／角色</th>${list.map(c=>`<th scope="col">${charName(c)}</th>`).join('')}</tr></thead><tbody>${levels.map(l=>`<tr><th scope="row">${esc(l.name)}<br>${levelCount(progress,data,l.id)}/16</th>${list.map(c=>cell(c,l)).join('')}</tr>`).join('')}</tbody></table>`;
 const mobileRows=filters.mobileAxis==='level'?chars.map(c=>[c,data.levels.find(l=>l.id===filters.mobileLevel)]):levels.map(l=>[data.characters.find(c=>c.id===filters.mobileCharacter),l]);
 return `<h1>角色通關矩陣</h1><p class="lead">本體 <strong id="matrix-count">${matrixCount(progress,data)} / 128</strong> 格。每關 10 名不同本體角色可提示 Conquered；角色八關全過提示個人獎盃。更新角色另組，不替代本體分母。</p><div class="toolbar">${search()}${scopeFilter()}${statusFilter()}${select('level','關卡',[['all','全部八關'],...data.levels.map(l=>[l.id,l.name])])}${select('character','角色',[['all','全部角色'],...data.characters.map(c=>[c.id,c.name])])}${select('sort','角色排序',[['default','原始順序'],['remaining','差幾格（少到多）'],['unlocked','已開放優先']])}<span class="desktop-matrix">${select('orientation','行列檢視',[['characters','角色為列'],['levels','關卡為列']])}</span></div><div class="desktop-matrix">${[['base','本體 · 16×8'],['updates','免費更新 · 獨立追蹤']].map(([set,label])=>{const list=chars.filter(c=>set==='base'?c.contentSet==='base':c.contentSet!=='base');return `<h2>${label}</h2><div class="table-frame">${list.length?table(list):empty()}</div>`;}).join('')}</div><div class="mobile-matrix"><div class="toolbar">${select('mobileAxis','勾選方式',[['level','先選關卡'],['character','先選角色']])}${filters.mobileAxis==='level'?select('mobileLevel','目前關卡',data.levels.map(l=>[l.id,l.name])):select('mobileCharacter','目前角色',data.characters.map(c=>[c.id,c.name]))}</div>${mobileRows.filter(([c,l])=>c&&l).map(([c,l])=>`<div class="row">${checkbox('clears',clearId(c.id,l.id),filters.mobileAxis==='level'?c.name:l.name,'mobile-')}<small>${characterCount(progress,data,c.id)}/8 角色 · ${levelCount(progress,data,l.id)}/16 本關 · ${esc(setNames[c.contentSet])}</small></div>`).join('')||empty()}</div>`;
}
function trophies(){const list=data.trophies.filter(t=>match(t.name,t.condition)).filter(t=>filters.status==='possible'?condition(progress,data,t).possible&&!progress.trophyEarned[t.id]:filters.status==='required'||statusMatch(!!progress.trophyEarned[t.id]));return `<h1>64 座 PS5 獎盃</h1><p class="lead">已取得 <strong id="trophy-count">${counted(progress.trophyEarned,data.trophies)} / 64</strong>。PS5 跳盃後手動確認；條件提示不會自動勾選，也不會在取消矩陣時抹掉獎盃。</p><div class="toolbar">${search()}${select('status','獎盃篩選',[['all','全部 64 盃'],['pending','未取得'],['done','已取得'],['required','白金必要'],['possible','條件可能已達成']])}</div><p class="results">顯示 ${list.length} 項</p>${list.map(t=>{const c=condition(progress,data,t),r=data.recipes.find(r=>r.name===t.name);return `<article class="row" id="trophy-${t.id}"><div class="row-head">${checkbox('trophyEarned',t.id,t.name)}<span class="count">#${t.number}</span></div><p>${esc(t.condition)}</p><p class="${c.possible?'possible':'muted'}">${c.possible?'條件可能已達成 · ':''}${c.total!==undefined?`${c.count} / ${c.total} `:''}${esc(c.label)}</p>${r?link('recipes','查詢材料與前置鏈',{recipe:r.id}):''}${t.name==='Scholar'?link('encyclopedia','核對本站本體條目'):''}${metadata(t)}</article>`;}).join('')||empty()}`;}
function buildings(){const list=data.buildings.filter(b=>(filters.set==='all'||b.contentSet===filters.set)&&(filters.level==='all'||b.blueprintLevel===filters.level)&&(filters.category==='all'||b.category===filters.category)&&match(b.name,b.effect,categoryNames[b.category])&&statusMatch(!!progress.buildingBuilt[b.id]));return `<h1>基地與角色解鎖</h1><p class="lead">本站定位 ${data.buildings.length} 座建築／藍圖，總量待查。住房決定角色「已開放」提示。取得藍圖與建造分開紀錄；取消建造不撤銷已取得獎盃。</p><div class="toolbar">${search()}${select('level','藍圖關卡',[['all','全部關卡'],...data.levels.map(l=>[l.id,l.name])])}${select('category','用途',[['all','全部用途'],...Object.entries(categoryNames)])}${statusFilter()}${scopeFilter()}</div><p class="results">顯示 ${list.length} 項 · 成本與未核實效果保留待查</p>${list.map(b=>`<article class="row" id="building-${b.id}"><div class="row-head"><h2>${esc(b.name)}</h2><span class="tag">${esc(categoryNames[b.category])}</span></div><small>${esc(data.levels.find(l=>l.id===b.blueprintLevel)?.name||'關卡待查／基地提供')}</small><p>${esc(b.effect)}</p><div class="checks">${checkbox('blueprintObtained',b.id,'取得藍圖')}${checkbox('buildingBuilt',b.id,'已建造')}</div>${metadata(b)}</article>`).join('')||empty()}<h2>資源地塊（另列，不計建築／藍圖分母）</h2><p>${data.resourcePlots.map(r=>esc(r.name)+'：'+esc(r.effect)).join('；')}</p><h2>角色池</h2>${data.characters.filter(c=>match(c.name,c.housing)).map(c=>`<div class="row"><strong>${esc(c.name)}</strong> · ${unlocked(progress,c)?'已開放':'住房待建'}<p>${esc(c.housing)}${c.id==='ballbearer'?' · 官方：雙倍戰球槽，沒有 Passive 槽。':c.id==='hoary-hoarder'?' · 官方：兩個戰球槽，Passive 槽倍增。':''}</p><small>技能完整數值／成本待查 · ${esc(setNames[c.contentSet])}</small></div>`).join('')}`;}
const itemById=id=>[...data.balls,...data.passives].find(r=>r.id===id);
function tree(id,path=[]){const item=itemById(id),recipe=data.recipes.find(r=>r.id===id),name=item?.name||recipe?.name||id;if(path.includes(id))return `<li>${esc(name)} · 配方循環／來源待核</li>`;if(!recipe)return `<li>${esc(name)} <small>${item?'基礎材料；'+verification(item):'尚未核實原料資料'}</small>${item?`<small> · ${esc(setNames[item.contentSet])} · ${sourceLinks(item)}</small>`:''}</li>`;return `<li>${esc(name)} <small>${esc(verification(recipe))} · ${sourceLinks(recipe)}</small>${recipe.ingredients.length?`<ul>${recipe.ingredients.map(branch=>branch.length>1?`<li>任選一種<ul>${branch.map(m=>tree(m,[...path,id])).join('')}</ul></li>`:tree(branch[0],[...path,id])).join('')}</ul>`:'<p>尚未核實完整配方；不能判定不存在。</p>'}</li>`;}
function recipeTerms(id,path=[]){if(path.includes(id))return [];const r=data.recipes.find(r=>r.id===id);return [itemById(id)?.name||r?.name||id,...(r?.ingredients.flat()||[]).flatMap(m=>recipeTerms(m,[...path,id]))];}
function recipes(){const selected=new URL(location.href).searchParams.get('recipe');const list=data.recipes.filter(r=>(!selected||r.id===selected)&&(filters.set==='all'||r.contentSet===filters.set)&&(filters.kind==='all'||r.kind===filters.kind)&&match(recipeTerms(r.id))&&statusMatch(!!progress.recipeMade[r.id]));return `<h1>Evolution 與 Passive</h1><p class="lead">Fusion 將兩顆球能力結合；Evolution 依指定材料產生具名新球；Evolved Passive 是被動能力組合。分支材料可替代，展開後逐層查前置。已製作與圖鑑解鎖分開確認。</p><div class="toolbar">${search()}${scopeFilter()}${select('kind','配方類別',[['all','全部配方'],['evolution','Evolution 戰球'],['evolved-passive','Evolved Passive']])}${statusFilter()}${selected?link('recipes','顯示全部配方'):''}</div><p class="notice">已收錄 ${data.recipes.length} 組具名配方。Wiki 直接頁受限，研究表以搜尋索引核對；來源差異逐筆保留。找不到的名稱是「尚未核實」，不能據此判定不存在。</p><p class="results">顯示 ${list.length} 項</p>${list.map(r=>{const enc=data.encyclopedia.find(e=>e.itemId===r.id);return `<article class="row" id="recipe-${r.id}"><div class="row-head"><h2>${esc(r.name)}</h2><span class="tag">${r.kind==='evolution'?'Evolution':'Evolved Passive'}</span></div><p>${r.ingredients.map(branch=>branch.map(id=>esc(itemById(id)?.name||id)).join(' 或 ')).join(' + ')||'尚未核實完整配方'}</p><div class="item-actions">${checkbox('recipeMade',r.id,'已製作')}${enc?checkbox('encyclopediaUnlocked',enc.id,'圖鑑已解鎖'):''}</div><details ${selected?'open':''}><summary>遞迴前置材料與來源</summary><ul class="material-tree">${tree(r.id)}</ul></details>${r.note?`<p class="meta">${esc(r.note)}</p>`:''}${metadata(r)}</article>`;}).join('')||empty()}`;}
function encyclopedia(){const list=data.encyclopedia.filter(r=>(filters.set==='all'||r.contentSet===filters.set)&&(filters.kind==='all'||r.kind===filters.kind)&&match(r.name)&&statusMatch(!!progress.encyclopediaUnlocked[r.id]));return `<h1>Encyclopedia</h1><p class="lead">本站已收錄 ${data.encyclopedia.length} 項戰球／Passive，已勾選 ${counted(progress.encyclopediaUnlocked,data.encyclopedia)} 項。這是已收錄範圍，沒有遊戲內 100% 分母。建築不混入圖鑑。</p><p class="notice">Scholar 只需本體。即使本站本體條目全部勾選，也不能判定完整圖鑑或自動取得 Scholar；其他圖鑑類型／完整總量待核實。更新項目為推薦體驗。</p><div class="toolbar">${search()}${scopeFilter()}${select('kind','條目類別',[['all','全部類別'],['ball','戰球'],['passive','Passive']])}${statusFilter()}</div>${Object.entries(setNames).map(([set,label])=>{const rows=list.filter(r=>r.contentSet===set);return rows.length?`<section><h2>${label} · 本站收錄 ${rows.length} 項／已勾選 ${counted(progress.encyclopediaUnlocked,rows)} 項</h2>${rows.map(r=>`<article class="row">${checkbox('encyclopediaUnlocked',r.id,r.name)}<small>${r.kind==='ball'?'戰球':'Passive'}${data.recipes.some(x=>x.id===r.itemId)?' · '+link('recipes','查詢配方',{recipe:r.itemId}):''}</small>${metadata(r)}</article>`).join('')}</section>`:'';}).join('')||empty()}`;}
function sources(){return `<h1>來源與覆蓋</h1><p class="lead">資料版本 ${esc(data.version)} · 查閱日期 ${esc(data.checkedAt)}。網站內部 ID 不是官方 PSN ID；進度從零開始，沒有讀取 PS5 存檔。</p><h2>本次收錄</h2><ul class="coverage-list"><li>8/8 關、16/16 本體角色、128/128 本體通關格、64/64 PS5 獎盃。</li><li>6 名免費更新角色，通關獨立記錄；不加入本體 128 格。</li><li>${data.buildings.length} 筆建築、${data.balls.length} 戰球、${data.passives.length} Passive、${data.recipes.length} 配方、${data.encyclopedia.length} 個可追蹤圖鑑條目；除規格已確認總量，其餘不宣稱遊戲全量。</li></ul><h2>待核實任務</h2><ul class="coverage-list">${data.coverage.limitations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2>來源紀錄</h2>${data.sourceRefs.filter(s=>s.access!=='local_spec').map(s=>`<div class="row"><strong>${esc(s.id)} · ${esc(s.label)}</strong><p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">開啟來源 ↗</a> · ${esc(s.access==='search_index'?'搜尋索引核對；直接頁面 403':s.access==='read'?'已讀取頁面':'依本次規格來源紀錄')}</p><small>${esc(s.note)} · ${esc(s.checkedAt)}</small></div>`).join('')}<h2>資料保存</h2><p>本機獨立 IndexedDB，不使用 Drive、SW 或中央帳號。瀏覽器資料可能被清除，請定期下載完整 JSON。失敗時保留原資料與匯入原文，不用空資料覆寫。</p>`;}
function advice(){const rows=data.advice.characters.filter(r=>match(r.id,r.mechanic,r.buildIdea,data.characters.find(c=>c.id===r.id)?.name)&&(filters.set==='all'||data.characters.find(c=>c.id===r.id)?.contentSet===filters.set));return `<h1>角色配裝與基地</h1><p class="lead">角色機制有來源；配裝方向是依機制與已核對配方的推論，尚未 PS5 實測。優先利用目前已開放的角色與材料，不以固定配置作通關門檻。</p><h2>基地發展順序示意</h2><p class="meta">原創功能順序示意，不是地形、實際格位或最佳相鄰配置；成本與建築倍率待查。</p><svg class="base-plan" viewBox="0 0 900 160" role="img" aria-label="基地發展順序：角色住房，資源生產，選項與槽位，指定獎盃，無限成長"><g fill="#f1f4f1" stroke="#c6cec8"><rect x="0" y="20" width="160" height="90" rx="5"/><rect x="185" y="20" width="160" height="90" rx="5"/><rect x="370" y="20" width="160" height="90" rx="5"/><rect x="555" y="20" width="160" height="90" rx="5"/><rect x="740" y="20" width="160" height="90" rx="5"/></g><g fill="#303a32" font-size="19" text-anchor="middle"><text x="80" y="60">角色住房</text><text x="265" y="60">資源生產</text><text x="450" y="60">選項與槽位</text><text x="635" y="60">指定獎盃</text><text x="820" y="60">無限成長</text></g><g fill="#626862" font-size="13" text-anchor="middle"><text x="80" y="87">擴充輪替角色池</text><text x="265" y="87">依缺口建造經濟設施</text><text x="450" y="87">增加局內選擇空間</text><text x="635" y="87">核對藍圖與建造</text><text x="820" y="87">後期持續升級</text></g><g fill="#626862" font-size="18"><text x="165" y="72">→</text><text x="350" y="72">→</text><text x="535" y="72">→</text><text x="720" y="72">→</text></g></svg><ol class="base-plan-list"><li>角色住房：擴充輪替角色池。</li><li>資源生產：依缺口建造經濟設施。</li><li>選項與槽位：增加局內選擇空間。</li><li>指定獎盃：核對藍圖與建造。</li><li>無限成長：後期持續升級。</li></ol><p class="muted">推薦：先建能解鎖缺少角色的住房，依資源缺口補經濟，再提升可選項與槽位。依目前藍圖與成本調整順序，無須等上一組全部建成。${link('buildings','核對藍圖／已建造')}</p><h2>配方與清理技巧</h2>${data.advice.generalTips.map(t=>`<div class="row"><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p><div class="meta">${sourceLinks(t)}</div></div>`).join('')}<div class="toolbar">${search()}${scopeFilter()}</div><p class="results">顯示 ${rows.length} / 22 名角色</p>${rows.map(r=>{const c=data.characters.find(c=>c.id===r.id);return `<article class="row" data-advice="${c.id}"><h2>${esc(c.name)}</h2><p><strong>機制：</strong>${esc(r.mechanic)}</p><p><strong>配裝方向（推論）：</strong>${esc(r.buildIdea)}</p><small>${esc(r.note)}</small><p>${link('matrix','記錄角色通關',{character:c.id})} · ${link('recipes','查詢配方與替代材料')}</p>${metadata({...r,contentSet:c.contentSet})}</article>`;}).join('')||empty()}`;}
const renderers={overview,roadmap,matrix,trophies,buildings,recipes,encyclopedia,advice,sources};
function render(preserve=false){if(!data||!progress)return;const active=document.activeElement,id=active?.id,selection=active?.selectionStart,scrollY=window.scrollY;const current=view();$('nav').innerHTML=Object.entries(names).map(([key,label])=>`<a data-route href="${route(key)}" ${key===current?'aria-current="page"':''}>${label}</a>`).join('');$('app').innerHTML=renderers[current]();$('data-version').textContent=data.version;$('save-state').textContent=blocked?'儲存不可用':'已保存本機 · r'+progress.revision;if(preserve&&id){const el=$(id);el?.focus({preventScroll:true});if(el?.type==='search'&&selection!==null)el.setSelectionRange(selection,selection);window.scrollTo(0,scrollY);}}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();const url=new URL(a.href);navigate(url.searchParams.get('view'),Object.fromEntries([...url.searchParams].filter(([k])=>k!=='view')));}const p=e.target.closest('[data-peek]');if(p){peek.has(p.dataset.peek)?peek.delete(p.dataset.peek):peek.add(p.dataset.peek);render(true);}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();});
document.addEventListener('input',e=>{if(e.target.type==='search'&&e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render(true);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.group)void action(async()=>{if(blocked)throw Error('儲存不可用；請匯出 JSON。');const group=el.dataset.group,id=el.dataset.id,value=el.checked;if(!groups.includes(group))throw Error('進度群組無效');try{await store.update(p=>{Object.defineProperty(p[group],id,{value,enumerable:true,writable:true,configurable:true});return p;});}catch(e){render(true);throw e;}});else if(el.dataset.filter){filters[el.dataset.filter]=el.value;render(true);}else if(el.id==='stage-select'){history.replaceState(null,'',route('roadmap',{level:el.value}));render(true);}});
$('nav-toggle').onclick=()=>{const open=$('nav-toggle').getAttribute('aria-expanded')!=='true';$('nav-toggle').setAttribute('aria-expanded',String(open));document.querySelector('.rail').classList.toggle('nav-open',open);};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.rail').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('popstate',()=>render());
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));try{const a=document.createElement('a');a.href=url;a.download='ball-x-pit-'+name+'.json';a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
$('open-backup').onclick=()=>$('backup-dialog').showModal();
$('export').onclick=()=>void action(async()=>{download(await store.exportAll(),'backup');$('backup-status').textContent='已送出完整下載，請確認保存。';});
function importControls(){const ready=review?.downloaded&&!review?.stale;$('import-ack').disabled=!ready;$('import-apply').disabled=!ready||!$('import-ack').checked||review.choices.some(c=>!c);}
function renderDiffs(){$('import-rows').replaceChildren();for(const c of review.preserved||[]){const div=document.createElement('div');div.className='diff';const title=document.createElement('strong');title.textContent=c.path.join(' / ');const pre=document.createElement('pre');pre.textContent=(c.local===undefined?'匯入新增（保留）':'僅本機存在（保留）')+'\n'+JSON.stringify(c.local===undefined?c.remote:c.local,null,2);div.append(title,pre);$('import-rows').append(div);}review.plan.conflicts.forEach((c,i)=>{const div=document.createElement('div');div.className='diff';const title=document.createElement('strong');title.textContent=c.path.join(' / ');const values=document.createElement('div');values.className='diff-values';for(const side of ['local','remote']){const pre=document.createElement('pre');pre.textContent=(side==='local'?'本機':'匯入')+'\n'+(JSON.stringify(c[side],null,2)??'（無紀錄）');values.append(pre);}const sel=document.createElement('select');sel.setAttribute('aria-label','匯入差異 '+(i+1));for(const [v,text]of [['','請選擇'],['local','保留本機'],['remote','使用匯入']])sel.add(new Option(text,v));sel.value=review.choices[i];sel.onchange=()=>{review.choices[i]=sel.value;importControls();};div.append(title,values,sel);$('import-rows').append(div);});}
$('import-file').onchange=()=>void action(async()=>{const file=$('import-file').files[0];$('import-file').value='';if(!file)return;review=null;if(file.size>5*1024*1024)throw Error('匯入超過 5 MiB，已停止。');const sourceRaw=await file.text(),localRaw=JSON.stringify(await store.raw());await store.archive({kind:'import-raw',at:Date.now(),sourceRaw,localRaw});const incoming=parseImport(JSON.parse(sourceRaw),$('recovery-side').value),local=validateProgress(JSON.parse(localRaw));const full=core.merge(null,local,incoming,{hasBase:false});const preserved=full.conflicts.filter(c=>c.local===undefined||c.remote===undefined),conflicts=full.conflicts.filter(c=>c.local!==undefined&&c.remote!==undefined),merged=core.resolve(full,full.conflicts.map(c=>c.local===undefined?'remote':'local'));review={sourceRaw,localRaw,stamp:localRaw,preserved,plan:{...full,data:merged,conflicts},choices:conflicts.map(()=>''),downloaded:false,stale:false};$('import-summary').textContent=`${conflicts.length} 筆兩端差異需選擇；${preserved.length} 筆單端項目自動保留／新增。空清單不會刪除本機紀錄，兩端原文完整保護。`;$('import-ack').checked=false;$('import-status').textContent='比較差異後，下載兩端備份並確認保存。';renderDiffs();importControls();$('backup-dialog').close();$('import-dialog').showModal();});
for(const [id,choice]of [['import-local','local'],['import-source','remote']])$(id).onclick=()=>{if(!review)return;review.choices.fill(choice);renderDiffs();importControls();};
$('import-download').onclick=()=>void action(async()=>{if(!review)return;review.downloaded=false;$('import-ack').checked=false;importControls();try{download({gameId:'ball-x-pit',recoveryBundle:{sourceRaw:review.sourceRaw,localRaw:review.localRaw},at:Date.now()},'before-import');review.downloaded=true;$('import-status').textContent='已送出兩端備份，請確認檔案保存。';}catch(e){$('import-status').textContent='備份失敗：'+e.message;}importControls();});
$('import-ack').onchange=importControls;
$('import-apply').onclick=()=>void action(async()=>{if(!review||!review.downloaded||review.stale||!$('import-ack').checked)return;try{await store.update(()=>validateProgress(core.resolve(review.plan,review.choices)),review.stamp);$('import-dialog').close();review=null;message('已套用選擇；兩端原文仍可完整匯出。');}catch(e){review.stale=true;$('import-status').textContent=e.message;importControls();}});
try{const response=await fetch(new URL('data/catalog.json',import.meta.url));if(!response.ok)throw Error('攻略資料讀取失敗；請重新整理。');data=await response.json();configureCatalog(data);progress=await store.open();const level=new URL(location.href).searchParams.get('level');if(data.levels.some(l=>l.id===level)){filters.level=filters.mobileLevel=level;}render();}catch(e){blocked=true;$('save-state').textContent='進度不可用';$('app').innerHTML='<h1>進度無法讀取</h1><p>'+esc(e.message)+'</p><p>原始資料未覆寫。請由備份下載原文；儲存不可用時可重試重新整理。</p>';}
